    def _parse_parameters_section(self, section: str) -> List[str]:
        fields = self._consume_fields()
        if self._config.napoleon_use_param:
            # Expand combined parameter names (e.g., "x1, x2") so that each
            # name gets its own ``:param`` entry with the same type and
            # description.  This matches the NumPy docstring behaviour.
            expanded_fields = []
            for field in fields:
                # ``field`` is a mapping with at least a ``name`` key.
                # Split on commas, strip whitespace, and create a separate
                # entry for each name.
                raw_name = field.get('name', '')
                names = [n.strip() for n in raw_name.split(',') if n.strip()]
                for name in names:
                    new_field = field.copy()
                    new_field['name'] = name
                    expanded_fields.append(new_field)
            return self._format_docutils_params(expanded_fields)
        else:
            return self._format_fields(_('Parameters'), fields)
